  const out = [];
  for (const op of operations) {
    if (op[0] === 'get') {
      const k = op[1];
      if (cache.has(k)) {
        const v = cache.get(k);
        cache.delete(k);
        cache.set(k, v);
        out.push(v);
      } else {
        out.push(-1);
      }
    } else {
      const k = op[1], v = op[2];
      if (cache.has(k)) cache.delete(k);
      cache.set(k, v);
      if (cache.size > capacity) cache.delete(cache.keys().next().value);
      out.push(null);
    }
  }
  return out;
}

